function MobileThemeSelector($return_config = false)
{    
	global $txt, $scripturl, $context, $sourcedir, $modSettings;

	$context[$context['admin_menu_name']]['tab_data']['title'] = $txt['select_theme_for_mobile_title'];
	$context[$context['admin_menu_name']]['tab_data']['description'] = $txt['mobile_theme_selector'];	

	require_once($sourcedir . '/ManageServer.php');
    require_once($sourcedir . '/Themes.php');
    ThemeList();

    // Set title and default sub-action.
    $context['sub_template'] = 'show_settings';
    $context['page_title'] = $txt['select_theme_for_mobile_title'];	

	$config_vars = array(
	    array('check', 'enable_mobile_theme_selector'),
	);

	$themes = array();
	foreach ($context['themes'] as $i => $theme)
		$themes[$theme['id']] = $theme['name'];

	$config_vars[] = array('select', 'mobile_theme_selector', $themes);

	if (isset($_GET['save']))
	{
		saveDBSettings($config_vars);
		redirectexit('action=admin;area=modsettings;sa=mobile_theme');
	}
	$context['post_url'] = $scripturl .'?action=admin;area=modsettings;sa=mobile_theme;save';	
	prepareDBSettingContext($config_vars);		
}

